def format_price(price) -> str:
    if price is None:
        return "N/A"
    try:
        return f"{float(price) * 100:.1f}%"
    except Exception:
        return str(price)


def format_volume(volume) -> str:
    if volume is None:
        return "N/A"
    try:
        v = float(volume)
        if v >= 1_000_000:
            return f"${v/1_000_000:.1f}M"
        elif v >= 1_000:
            return f"${v/1_000:.1f}K"
        else:
            return f"${v:.0f}"
    except Exception:
        return str(volume)
